def caesar_brute_force(text):
    for versatz in range(1, 26):
        ergebnis = ""
        for zeichen in text:
            if zeichen.isalpha():
                basis = ord(''A'') if zeichen.isupper() else ord(''a'')
                ergebnis += chr((ord(zeichen) - basis - versatz) % 26 + basis)
            else:
                ergebnis += zeichen
        print(f'Versatz {versatz:2}: {ergebnis}')

caesar_brute_force('KHOOR')
